<?php
declare(strict_types=1);
namespace CommunityHub;
final class Jobs {
 public static function staleServers():void{$servers=App::rows("SELECT id FROM fivem_servers WHERE last_heartbeat_at IS NULL OR last_heartbeat_at<=DATE_SUB(NOW(),INTERVAL 90 SECOND)");foreach($servers as $s)App::transaction(function()use($s){$s=App::row('SELECT *,NOW() observed_at FROM fivem_servers WHERE id=? FOR UPDATE',[$s['id']]);if($s['last_heartbeat_at']&&strtotime($s['observed_at'])-strtotime($s['last_heartbeat_at'])<90)return;$p=App::row('SELECT * FROM fivem_status_periods WHERE server_id=? AND open_marker=1',[$s['id']]);if(!$p||$p['state']==='online'){$at=$s['last_heartbeat_at']?date('Y-m-d H:i:s',max(strtotime($p['started_at']??$s['last_heartbeat_at']),strtotime($s['last_heartbeat_at'])+90)):$s['observed_at'];App::query('UPDATE fivem_status_periods SET ended_at=?,open_marker=NULL WHERE server_id=? AND open_marker=1',[$at,$s['id']]);App::query("INSERT INTO fivem_status_periods(server_id,state,started_at) VALUES(?,'offline',?)",[$s['id'],$at]);}App::query('UPDATE fivem_servers SET is_online=0 WHERE id=?',[$s['id']]);});}
 public static function run():array{$lock=App::row("SELECT GET_LOCK('communityhub_php_jobs',0) acquired");if(empty($lock['acquired']))return ['skipped'=>true];try{self::staleServers();$restored=People::restoreLeave();People::readiness();App::query('DELETE FROM php_rate_limits WHERE expires_at<NOW()');App::query('DELETE FROM php_sessions WHERE expires_at<NOW()');App::query('DELETE FROM fivem_link_codes WHERE expires_at<NOW()');return ['ok'=>true,'leave_restored'=>$restored];}finally{App::query("SELECT RELEASE_LOCK('communityhub_php_jobs')");}}
}
